compose:
services:
  adblock:
    image: fah-adblock:latest
    restart: unless-stopped
    network_mode: host
    environment:
      - TZ=${ZEITZONE}
      - DNS_BIND=${DNS_ADRESSE}
      - DNS_PORT=${PORT_DNS}
      - WEB_PORT=${PORT_WEB}
      - GATEWAY=${GATEWAY}
      - ERLAUBTE_NETZE=${ERLAUBTE_NETZE}
      - SESSION_SECRET=${SITZUNGSGEHEIMNIS}
      - VERTRAUTE_PROXIES=${VERTRAUTE_PROXYS}
      - LOKALE_ZONEN=${LOKALE_ZONEN}
    volumes:
      - "${PFAD_DATEN}:/app/data"
    cap_drop:
      - ALL
    cap_add:
      - NET_BIND_SERVICE
    security_opt:
      - no-new-privileges:true
    mem_limit: 768m
